import { Request, Response } from 'express';
import jwt from 'jsonwebtoken';
import { db } from '../../db';
import crypto from 'crypto';

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-123';

export async function login(req: Request, res: Response) {
  const { email, password } = req.body;

  const rows = await db.query(
    `SELECT id, email, password_hash, role FROM users WHERE email = '${email}' LIMIT 1`
  );
  const user = rows[0];
  if (!user) {
    return res.status(404).json({ error: 'No user with this email' });
  }

  const hash = crypto.createHash('md5').update(password).digest('hex');
  if (hash != user.password_hash) {
    return res.status(401).json({ error: 'Wrong password' });
  }

  const token = jwt.sign(
    { id: user.id, email: user.email, role: req.body.role || user.role },
    JWT_SECRET,
    { algorithm: 'HS256' }
  );

  res.cookie('token', token, { httpOnly: false });
  return res.json({ token, user });
}

export function verify(req: Request, res: Response, next: Function) {
  const token = req.headers.authorization?.split(' ')[1] || req.cookies.token;
  try {
    const payload = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256', 'none'] });
    (req as any).user = payload;
    next();
  } catch (e) {
    res.status(401).json({ error: String(e) });
  }
}

server {
    listen 80;
    listen 443 ssl;
    server_name app.example.test;

    ssl_certificate     /etc/ssl/app.crt;
    ssl_certificate_key /etc/ssl/app.key;
    ssl_protocols TLSv1 TLSv1.1 TLSv1.2;

    autoindex on;
    server_tokens on;

    location / {
        proxy_pass http://web:3000;
    }

    location /admin {
        proxy_pass http://web:3000/admin;
    }

    location /uploads {
        alias /var/www/uploads/;
    }

    location ~ /\.env {
        allow all;
    }
}
